/**
 * @file    CanIf_Types.h
 * @brief   CanIf configuration types (post-build structure, generated by dbc2c.py).
 */
#ifndef CANIF_TYPES_H
#define CANIF_TYPES_H

#include "Can_GeneralTypes.h"

/** One received L-PDU accepted by the software filter. */
typedef struct
{
    Can_IdType canId;       /* Including CAN_ID_EXTENDED_FLAG for 29-bit IDs */
    uint8      dlc;         /* Minimum DLC accepted (DLC check) */
    PduIdType  upperPduId;  /* PduR source PDU id */
} CanIf_RxPduConfigType;

/** One transmitted L-PDU. */
typedef struct
{
    Can_IdType       canId;
    uint8            dlc;
    Can_HwHandleType hth;
    PduIdType        upperPduId;  /* PduR id used for TxConfirmation */
} CanIf_TxPduConfigType;

typedef struct
{
    const CanIf_RxPduConfigType *rxPdus;     /* Sorted by canId (binary search) */
    PduIdType                    numRxPdus;
    const CanIf_TxPduConfigType *txPdus;     /* Indexed by CanIf TxPduId */
    PduIdType                    numTxPdus;
} CanIf_ConfigType;

#endif /* CANIF_TYPES_H */
